import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

const pin = (orgId: any, name: string, slug: string, key: string) => ({ orgId, name, slug, key, description: null, visibility: "org" as const, leadId: null, color: "#6366f1", targetDate: null });

describe("scratch", () => {
  it("everything", async () => {
    const off = registerUsageListeners();
    const t = await createTenant("scr", "free");
    await usageRepo.recomputeUsage(t.org.id);
    const a = t.actors.admin;
    const second = await projectService.createProject(a, pin(t.org.id, "Web Vendors", "web-vendors", "WV"));
    const dup = await projectRepo.insertProject(pin(t.org.id, "Web Visitors", "web-visitors", "WV"));
    expect(dup.key).toBe("WV2");
    await projectRepo.archiveProject(t.org.id, dup.id);
    // quota: 2 live (platform, second) + archived dup
    await expect(projectService.createProject(a, pin(t.org.id, "Third", "third", "THR"))).rejects.toThrow(/allows 2 projects/);
    await projectService.archiveProject(a, { orgId: t.org.id, projectId: second.id, archiveIssues: true });
    expect((await usageRepo.getUsage(t.org.id)).projectsUsed).toBe(1);
    const third = await projectService.createProject(a, pin(t.org.id, "Web Vendors", "web-vendors", "WV"));
    expect(third.slug).toBe("web-vendors-2");
    expect(third.key).toBe("WV3");
    expect((await usageRepo.getUsage(t.org.id)).projectsUsed).toBe(2);
    const got: unknown[] = [];
    const o2 = subscribe("project.restored", (p) => { got.push(p); });
    await expect(projectService.restoreProject(a, t.org.id, second.id)).rejects.toThrow(/allows 2 projects/);
    await expect(projectService.restoreProject(a, t.org.id, third.id)).rejects.toThrow();
    expect(got).toHaveLength(0);
    await projectService.archiveProject(a, { orgId: t.org.id, projectId: third.id, archiveIssues: true });
    const r = await projectService.restoreProject(a, t.org.id, second.id);
    expect(r.slug).toBe("web-vendors");
    expect(got).toHaveLength(1);
    const u = await usageRepo.getUsage(t.org.id);
    expect(u.projectsUsed).toBe((await usageRepo.recomputeUsage(t.org.id)).projectsUsed);
    expect(u.projectsUsed).toBe(2);
    o2(); off();
  });
  it("status", async () => {
    const t = await createTenant("scr2", "growth");
    const m = t.actors.member;
    const i = await issueService.createIssue(m, issueInput(t.org.id, t.project.id));
    await expect(projectService.updateProject(m, { orgId: t.org.id, projectId: t.project.id, status: "completed" })).rejects.toThrow();
